// HOSA Bowl Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items. HOSA facts follow the Valus HOSA lessons (HOSA Handbook and
// The First Fifty Years); current health topics use well-established public health issues.
import {q, mix} from './q.js';
const DHO='Simmers, DHO: Health Science', BSF='Scott & Bell, Body Structures and Functions', TAB='Taber’s Cyclopedic Medical Dictionary', MLP='NIH MedlinePlus', BRIEF='Robert’s Rules of Order Newly Revised In Brief', HB='HOSA Handbook and website';
const HOSA='HOSA Related Knowledge', PP='Parliamentary Procedure', AP='Anatomy and Physiology', MT='Medical Terminology', CUR='Current Health Topics', OTH='Remaining Categories';
const HM='History of Medicine', HS='Healthcare Systems', HC='Health Careers', LE='Legal and Ethical Practices', NUT='Nutrition', SAF='Safety', INF='Infection Control', MATH='Math Conversions';

export default {
 id:'hosa-bowl-1',
 event:'HOSA Bowl',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'DHO: Health Science, Body Structures and Functions, Taber’s, NIH MedlinePlus, RONR In Brief and HOSA publications',
 plan:[{area:HOSA,weight:12},{area:PP,weight:12},{area:AP,weight:12},{area:MT,weight:12},{area:CUR,weight:12},{area:OTH,weight:40,topics:[HM,HS,HC,LE,NUT,SAF,INF,MATH]}],
 questions:mix([
  q(HOSA,'In what year was HOSA founded?','1976',['1966','1986','1996'],'B','HOSA was founded in 1976 to give health science students leadership development and career preparation.',HB),
  q(HOSA,'HOSA’s mission is to empower members to become leaders in the global health community through:','Education, collaboration and experience',['Competition, travel and awards','Research, patents and funding','Volunteering, sports and music'],'D','These three words come from HOSA’s mission statement and are commonly tested in HOSA knowledge questions.',HB),
  q(HOSA,'HOSA is classified as what type of organization?','A career technical student group',['A professional licensing board','A hospital accreditation agency','A federal health agency'],'A','As a CTSO, HOSA is linked to health science education programs.',HB),
  q(HOSA,'Which divisions make up HOSA’s active student membership?','Middle school through collegiate',['Elementary, secondary and graduate','Alumni and professional only','Freshman through senior only'],'C','Alumni and professional members support students but are not active student members.',HB),
  q(HOSA,'What is the name of HOSA’s annual international conference?','International Leadership Conference',['National Skills Summit','World Health Assembly','Global Career Fair'],'B','At ILC, members compete in events and voting delegates conduct business and elect officers.',HB),
  q(HOSA,'Who elects HOSA’s Executive Council?','Voting delegates at ILC',['HOSA Headquarters staff','All members online','State Advisors only'],'D','Delegates evaluate candidates’ resumes, videos and interviews before electing officers for one-year terms.',HB),
  q(PP,'When is it appropriate for the presiding officer to vote on a motion?','When the vote would make or break a tie',['Whenever the officer has an opinion','On every motion','Never under any circumstances'],'A','In a large assembly, the chair remains impartial and votes only when it would change the result, or by ballot.',BRIEF),
  q(PP,'Which motion closes debate and requires a two-thirds vote?','Previous question',['Lay on the table','Adjourn','Postpone to a certain time'],'C','Closing debate limits members’ rights, so it requires two-thirds.',BRIEF),
  q(PP,'What is a quorum?','The minimum number needed for business',['The total membership of the group','The number of officers','The number of votes needed to pass a motion'],'B','Without a quorum, the group cannot take valid action, except to adjourn or take steps to obtain a quorum.',BRIEF),
  q(PP,'In what order are a primary amendment and a main motion voted on?','The amendment, then the main motion',['The main motion first','Both at once','Only the main motion is voted on'],'D','Motions are voted on in reverse order of their making, so the most recent (the amendment) is decided first.',BRIEF),
  q(PP,'Which motion temporarily sets aside a pending motion so the group can deal with something urgent?','Lay on the table',['Postpone indefinitely','Rescind','Previous question'],'A','Lay on the table should not be used to kill a motion. The motion can later be taken from the table.',BRIEF),
  q(PP,'During a voice vote, what do members say to vote yes?','“Aye”',['“Yea”','“Yes, chair”','“I agree”'],'C','The chair asks “Those in favor, say aye,” then “Those opposed, say no.” “Nay” is no longer used.',BRIEF),
  q(AP,'Which chamber of the heart receives oxygen-rich blood from the lungs?','Left atrium',['Right atrium','Right ventricle','Left ventricle'],'B','The pulmonary veins return oxygenated blood to the left atrium, which passes it to the left ventricle.',BSF),
  q(AP,'Which part of the brain coordinates balance and smooth movement?','Cerebellum',['Medulla oblongata','Hypothalamus','Frontal lobe'],'D','The medulla controls vital functions such as breathing; the hypothalamus regulates temperature and hormones.',BSF),
  q(AP,'Where in the kidney does blood filtration begin?','Glomerulus',['Loop of Henle','Collecting duct','Ureter'],'A','The glomerulus is a capillary network inside Bowman’s capsule where plasma is filtered.',BSF),
  q(AP,'Which gland is called the “master gland” because it controls many other endocrine glands?','Pituitary gland',['Thyroid gland','Adrenal gland','Pancreas'],'C','The pituitary releases hormones that regulate the thyroid, adrenal glands and gonads; it is itself controlled by the hypothalamus.',BSF),
  q(AP,'Where does most chemical digestion and nutrient absorption take place?','Small intestine',['Stomach','Large intestine','Esophagus'],'B','Villi and microvilli give the small intestine a huge surface area for absorption.',BSF),
  q(AP,'Which type of muscle is found in the walls of blood vessels and the digestive tract?','Smooth muscle',['Skeletal muscle','Cardiac muscle','Voluntary striated muscle'],'D','Smooth muscle is involuntary and nonstriated. Cardiac muscle is striated and found only in the heart.',BSF),
  q(MT,'What does the suffix -ectomy mean?','Surgical removal',['Surgical incision','Surgical repair','Visual examination'],'A','-tomy is incision, -plasty is repair and -scopy is visual examination.',TAB),
  q(MT,'What does the term bradycardia mean?','Slow heart rate',['Fast heart rate','Irregular heart rhythm','Enlarged heart'],'C','Brady- means slow and cardi/o means heart; an adult resting rate below 60 beats per minute is bradycardia.',TAB),
  q(MT,'Which prefix means “below” or “deficient”?','Hypo-',['Hyper-','Supra-','Epi-'],'B','Hypo- means under or below normal, as in hypoglycemia. Hyper- means above or excessive.',TAB),
  q(MT,'What does nephrolithiasis mean?','Kidney stones',['Inflammation of the kidney','Removal of a kidney','Kidney failure'],'D','Nephr/o (kidney) + lith/o (stone) + -iasis (abnormal condition) describes stones in the kidney.',TAB),
  q(MT,'Which combining form means “liver”?','hepat/o',['hem/o','hist/o','hyster/o'],'A','Hem/o means blood, hist/o means tissue and hyster/o means uterus.',TAB),
  q(MT,'What does the abbreviation NPO mean?','Nothing by mouth',['Normal physical outcome','No pain observed','New patient orientation'],'C','NPO comes from the Latin nil per os, used before surgery and some tests.',TAB),
  q(CUR,'Why is antibiotic resistance a growing public health concern?','Bacteria evolve to survive the drugs',['Antibiotics now cure viral infections','Bacteria no longer cause disease','Antibiotics have become cheaper'],'B','Overuse and misuse of antibiotics speed resistance. Completing prescribed courses and avoiding unnecessary antibiotics help.',MLP),
  q(CUR,'Why has illicit fentanyl caused a sharp rise in overdose deaths?','It is extremely potent and often hidden',['It is weaker than other opioids','It is available only by prescription','It cannot cause breathing problems'],'D','Tiny amounts can stop breathing. Naloxone can reverse an opioid overdose.',MLP),
  q(CUR,'Why do public health officials warn teens about vaping?','Nicotine is addictive and harms brain development',['Vapes contain only harmless water vapor','Vaping improves lung function','Vaping is safer than drinking water'],'A','Nicotine is highly addictive for developing brains, and vape aerosols can also contain harmful chemicals and metals.',MLP),
  q(CUR,'Why have measles outbreaks returned in some communities?','Lower vaccination rates leave more people unprotected',['The measles virus has disappeared worldwide','The vaccine no longer works','Measles now spreads only through food'],'C','Measles is extremely contagious; high two-dose MMR coverage is needed to prevent outbreaks.',MLP),
  q(CUR,'Which group is at especially high risk during extreme heat events?','Older adults',['Young adults who exercise indoors','People in air-conditioned offices','Teens who drink plenty of water'],'B','Older adults, infants, outdoor workers and people with chronic illness are most vulnerable to heat-related illness.',MLP),
  q(CUR,'What is telehealth?','Remote care using technology',['Health care only in emergency rooms','A type of health insurance','A phone directory of doctors'],'D','Telehealth expanded rapidly during the COVID-19 pandemic and improves access in rural and underserved areas.',MLP),
  q(HM,'Who is known as the “Father of Medicine” for separating medicine from superstition?','Hippocrates',['Galen','Vesalius','Pasteur'],'A','Hippocrates taught that disease has natural causes. The Hippocratic Oath is named for him.',DHO),
  q(HM,'Who developed the first smallpox vaccine using cowpox?','Edward Jenner',['Louis Pasteur','Joseph Lister','Robert Koch'],'C','In 1796, Jenner showed that cowpox exposure protected against smallpox.',DHO),
  q(HM,'Who discovered penicillin in 1928?','Alexander Fleming',['Jonas Salk','Marie Curie','Wilhelm Roentgen'],'B','Fleming noticed mold killing bacteria on a culture plate. Penicillin became widely used in the 1940s.',DHO),
  q(HS,'Which government program provides health insurance mainly for people 65 and older?','Medicare',['Medicaid','CHIP','WIC'],'D','Medicaid serves people with low incomes, and CHIP covers children in families with modest incomes.',DHO),
  q(HS,'Which type of facility provides comfort care to people who are terminally ill?','Hospice',['Urgent care center','Rehabilitation hospital','Ambulatory surgery center'],'A','Hospice focuses on comfort and quality of life rather than cure.',DHO),
  q(HS,'In a health maintenance organization (HMO), members usually:','Have a primary provider manage referrals',['See any specialist without a referral','Pay no premiums','Must use emergency rooms for all care'],'C','HMOs emphasize prevention and cost control through a network of providers.',DHO),
  q(HC,'Which health professional analyzes body fluids and tissues to help diagnose disease?','Lab scientist',['Physical therapist','Dental hygienist','Respiratory therapist'],'B','Medical laboratory scientists perform tests in hematology, chemistry, microbiology and blood banking.',DHO),
  q(HC,'In the health science career clusters, which pathway includes radiologic technologists?','Diagnostic services',['Support services','Health informatics','Biotechnology research and development'],'D','Diagnostic services create a picture of health status through tests and evaluations.',DHO),
  q(HC,'What is the difference between licensure and certification?','Licensure is state-required; certification is by a professional group',['Certification is required by law; licensure is voluntary','They mean the same thing','Licensure is granted only by hospitals'],'A','Licensure protects the public by limiting practice to qualified people.',DHO),
  q(LE,'Under HIPAA, which action is a privacy violation?','Discussing a patient’s diagnosis in a public hallway',['Sharing records with the patient’s treating doctor','Giving a patient a copy of their own record','Reporting a communicable disease as required by law'],'C','Protected health information may be shared for treatment and required reporting, but not casually in public.',DHO),
  q(LE,'Touching a patient without their consent is which legal wrong?','Battery',['Assault','Slander','Libel'],'B','Assault is a threat that causes fear of harmful touching; battery is the actual unauthorized touching.',DHO),
  q(LE,'What is malpractice?','Professional negligence causing harm',['Any mistake that causes no harm','Refusing to work overtime','Reporting a coworker’s error'],'D','Malpractice requires a duty, a breach of the standard of care, and harm caused by that breach.',DHO),
  q(NUT,'Which vitamin is made in the skin when it is exposed to sunlight?','Vitamin D',['Vitamin C','Vitamin K','Vitamin B12'],'A','Vitamin D forms in skin exposed to UVB light and helps the body absorb calcium for strong bones.',DHO),
  q(NUT,'How many calories does one gram of fat provide?','9',['4','7','12'],'C','Carbohydrates and proteins provide 4 calories per gram, alcohol 7, and fat 9.',DHO),
  q(SAF,'What does the PASS method stand for when using a fire extinguisher?','Pull, Aim, Squeeze, Sweep',['Push, Alert, Spray, Stop','Point, Activate, Shake, Spray','Pull, Alert, Spray, Shut'],'B','Pull the pin, aim at the base of the fire, squeeze the handle and sweep side to side.',DHO),
  q(SAF,'Which body mechanics rule helps prevent back injuries when lifting?','Bend at the knees and keep the object close',['Bend at the waist with straight legs','Twist while lifting','Hold the object far from the body'],'D','A wide base of support and use of the strong leg muscles protect the back.',DHO),
  q(INF,'What is the single most important way to prevent the spread of infection?','Hand hygiene',['Wearing a gown at all times','Taking antibiotics','Avoiding all patient contact'],'A','Hand hygiene breaks the chain of infection at the mode of transmission.',DHO),
  q(INF,'Which process destroys all microorganisms, including spores?','Sterilization',['Sanitization','Disinfection','Antisepsis'],'C','Sanitization reduces microorganisms; disinfection kills most but not spores; sterilization kills all.',DHO),
  q(MATH,'A patient weighs 88 pounds. What is the weight in kilograms?','40 kg',['36 kg','44 kg','194 kg'],'B','Pounds are converted to kilograms by dividing by 2.2: 88 ÷ 2.2 = 40 kg.',DHO),
  q(MATH,'How many milliliters are in 2 teaspoons?','10 mL',['2 mL','5 mL','15 mL'],'D','1 teaspoon = 5 mL, so 2 teaspoons = 10 mL. A tablespoon is 15 mL, three times a teaspoon.',DHO)
 ],193)
};
